-- Apply with: psql "$DATABASE_URL" -f migrations/versions/0001_production_foundation.sql
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users (id uuid PRIMARY KEY, email varchar(320) UNIQUE NOT NULL, password_hash varchar(255) NOT NULL, role varchar(40) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE guests (id uuid PRIMARY KEY, name varchar(180) NOT NULL, phone varchar(40), email varchar(320), lifecycle varchar(24) NOT NULL DEFAULT 'lead', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE room_types (id uuid PRIMARY KEY, name varchar(80) UNIQUE NOT NULL, capacity integer NOT NULL CHECK (capacity > 0), rack_rate numeric(14,2) NOT NULL CHECK (rack_rate >= 0));
CREATE TABLE rooms (id uuid PRIMARY KEY, number varchar(20) UNIQUE NOT NULL, room_type_id uuid NOT NULL REFERENCES room_types, active boolean NOT NULL DEFAULT true);
CREATE TABLE reservations (id uuid PRIMARY KEY, code varchar(24) UNIQUE NOT NULL, guest_id uuid NOT NULL REFERENCES guests, room_id uuid NOT NULL REFERENCES rooms, check_in date NOT NULL, check_out date NOT NULL, stay_dates daterange GENERATED ALWAYS AS (daterange(check_in, check_out, '[)')) STORED, adults integer NOT NULL CHECK (adults > 0), children integer NOT NULL DEFAULT 0 CHECK (children >= 0), rate numeric(14,2) NOT NULL, status varchar(24) NOT NULL DEFAULT 'confirmed', created_at timestamptz NOT NULL DEFAULT now(), CHECK (check_out > check_in));
ALTER TABLE reservations ADD CONSTRAINT no_overlapping_active_room_stays EXCLUDE USING gist (room_id WITH =, stay_dates WITH &&) WHERE (status IN ('confirmed','checked_in'));
CREATE TABLE room_availability (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms, business_date date NOT NULL, sellable boolean NOT NULL DEFAULT true, reason varchar(255), UNIQUE(room_id,business_date));
CREATE TABLE room_tasks (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms, kind varchar(20) NOT NULL CHECK (kind IN ('housekeeping','maintenance')), status varchar(20) NOT NULL DEFAULT 'open', opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE journal_entries (id uuid PRIMARY KEY, posted_on date NOT NULL, reference varchar(80) UNIQUE NOT NULL, status varchar(16) NOT NULL DEFAULT 'posted', memo text NOT NULL);
CREATE TABLE journal_lines (id uuid PRIMARY KEY, entry_id uuid NOT NULL REFERENCES journal_entries, account_code varchar(32) NOT NULL, debit numeric(14,2) NOT NULL DEFAULT 0, credit numeric(14,2) NOT NULL DEFAULT 0, CHECK ((debit = 0) <> (credit = 0)));
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor_id uuid REFERENCES users, action varchar(120) NOT NULL, entity_type varchar(80) NOT NULL, entity_id varchar(80) NOT NULL, before_json text, after_json text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events (id uuid PRIMARY KEY, reservation_id uuid REFERENCES reservations, provider varchar(32) NOT NULL, provider_reference varchar(120) UNIQUE NOT NULL, amount numeric(14,2) NOT NULL, status varchar(24) NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pos_transactions (id uuid PRIMARY KEY, reservation_id uuid REFERENCES reservations, business_date date NOT NULL, outlet varchar(80) NOT NULL, reference varchar(80) UNIQUE NOT NULL, status varchar(20) NOT NULL DEFAULT 'posted', net_amount numeric(14,2) NOT NULL, tax_amount numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE payment_reconciliations (id uuid PRIMARY KEY, payment_event_id uuid NOT NULL REFERENCES payment_events, settlement_reference varchar(120) UNIQUE NOT NULL, settled_on date NOT NULL, status varchar(20) NOT NULL DEFAULT 'settled');
CREATE TABLE refunds (id uuid PRIMARY KEY, payment_event_id uuid NOT NULL REFERENCES payment_events, reference varchar(120) UNIQUE NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), status varchar(24) NOT NULL, requested_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_items (id uuid PRIMARY KEY, sku varchar(80) UNIQUE NOT NULL, name varchar(180) NOT NULL, quantity numeric(14,3) NOT NULL DEFAULT 0, reorder_level numeric(14,3) NOT NULL DEFAULT 0);
CREATE TABLE inventory_movements (id uuid PRIMARY KEY, item_id uuid NOT NULL REFERENCES inventory_items, movement_type varchar(24) NOT NULL, quantity numeric(14,3) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), reference varchar(100) NOT NULL);
CREATE TABLE purchase_orders (id uuid PRIMARY KEY, supplier_name varchar(180) NOT NULL, status varchar(24) NOT NULL DEFAULT 'draft', ordered_on date NOT NULL, received_on date);
